import{_ as a,c as e,a2 as r,o as l}from"./chunks/framework.CO0qOYmW.js";const m=JSON.parse('{"title":"LLMOps 质量工程概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/08-llmops-quality/01-evaluation/01-overview.md","filePath":"ai/08-llmops-quality/01-evaluation/01-overview.md","lastUpdated":1783608971000}'),o={name:"ai/08-llmops-quality/01-evaluation/01-overview.md"};function i(d,t,s,n,h,p){return l(),e("div",null,t[0]||(t[0]=[r('<h1 id="llmops-质量工程概述" tabindex="-1">LLMOps 质量工程概述 <a class="header-anchor" href="#llmops-质量工程概述" aria-label="Permalink to &quot;LLMOps 质量工程概述&quot;">​</a></h1><p>LLMOps 质量工程关注 AI 应用上线后的效果评测、链路追踪、质量优化、灰度发布和持续反馈。它解决的是 AI 应用不可控、不可测、不可回归和难以稳定迭代的问题。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><ul><li><strong>让效果可评估</strong>：通过评测集、Golden Answer、自动评分和人工评审衡量质量。</li><li><strong>让问题可定位</strong>：通过 Trace、Prompt 日志、Token、延迟和失败分析定位问题。</li><li><strong>让迭代可回归</strong>：通过版本管理、灰度发布、A/B 测试和回滚保障稳定性。</li></ul><h2 id="质量体系" tabindex="-1">质量体系 <a class="header-anchor" href="#质量体系" aria-label="Permalink to &quot;质量体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>评测体系</td><td>构建测试集、基准答案、评分规则和人工评审流程</td></tr><tr><td>可观测性</td><td>记录 Prompt、模型响应、检索结果、工具调用和成本指标</td></tr><tr><td>质量优化</td><td>治理幻觉、相关性、可引用性和用户反馈闭环</td></tr><tr><td>发布管理</td><td>管理 Prompt 灰度、A/B 测试、版本回滚和事故复盘</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>先建立评测集和质量指标，明确什么叫回答得好。</li><li>再接入 Trace 和日志，保证每次模型调用都可以追踪。</li><li>最后建立灰度、回滚和反馈闭环，让 AI 应用可以持续迭代。</li></ol>',8)]))}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
